/**
 * Real outputs, with the exact prompts that produced them.
 *
 * Every entry here was generated by this product through the tool it is filed under — nothing is
 * stock, and no prompt is reconstructed after the fact. That matters twice over: the gallery is
 * the proof that the tool is good, and clicking an example loads its real prompt into the field,
 * so the fastest way to learn what a good brief looks like is to run one.
 *
 * When adding entries: generate through the tool, keep the prompt verbatim, and check the result
 * carries no third-party trademark or real person's likeness before shipping it as marketing.
 *
 * Assets live in `public/showcase/` rather than the `.data/` runtime cache, which is gitignored —
 * served from there they would 404 on a fresh clone, which is exactly what a reviewer sees first.
 * They are re-encoded for the web on the way in (PNG -> WebP, H.264 CRF 28), taking the showcase
 * set from 181 MB to 19 MB without a visible difference at display size.
 */
export interface ToolExample {
  uri: string;
  kind: "image" | "video" | "text" | "compare";
  /** The verbatim prompt. Omit only for assets whose original prompt isn't recoverable. */
  prompt?: string;
  /** Short label used when there is no prompt to show. */
  caption?: string;
  /** For kind "compare": the lower-resolution original the result is measured against. */
  before?: string;
  /** For kind "text": the output the tool produced from `uri`. */
  output?: string;
  /** True pixel dimensions. When present the tile is rendered at this exact ratio rather than
   *  being squared off — on a platform page the shape of a format is part of the information. */
  width?: number;
  height?: number;
}

