/**
 * One verified example per advertised platform size.
 *
 * Every entry was generated through Text→Image at exactly the dimensions the nav menu promises,
 * and each file was checked on disk to confirm it really is that size — this table is the
 * evidence behind "exact pixels for every platform", not a restatement of it. Keyed by the same
 * `platform` and `format` values the deep links use.
 */
export interface SizeExample {
  format: string;
  width: number;
  height: number;
  uri: string;
  prompt: string;
  /** Video formats (Shorts, Reel, TikTok Video) carry a clip; omitted means a still. */
  kind?: "image" | "video";
}

/** Gallery tiles are capped at this height; below it they draw at intrinsic size. */
export const TILE_MAX_HEIGHT = 340;

/**
 * How many examples a format gets, derived rather than guessed.
 *
 * A tile keeps its true aspect and never exceeds TILE_MAX_HEIGHT, so its rendered width is
 * `min(naturalWidth, cap * ratio)` — and how many fit across the canvas follows from that. Coarse
 * ratio bands got this wrong in both directions: a 1:2.1 Pinterest pin draws only ~162px wide so
 * five fit, while a 2560×1440 banner draws ~605px so exactly one does.
 *
 * Capped at three so every format renders as one row. Sanity check against the shapes in use:
 * banner 1, avatar 2, square post 2, 4:5 post 3, 9:16 story 3, 2:3 pin 3, long pin 3.
 */
export function exampleTarget(width: number, height: number, canvasWidth = 1000, gap = 10): number {
  const rendered = Math.min(width, TILE_MAX_HEIGHT * (width / height));
  // Capped at three: a single row reads as a set, while a second row of the same thing is
  // padding. Anything that only fits one or two keeps that smaller number.
  return Math.max(1, Math.min(3, Math.floor(canvasWidth / (rendered + gap))));
}

/**
 * The one creative the generic "Social Post" page for each platform stands for.
 *
 * A platform page reached without a named format used to show every format that platform has, so
 * a 9:16 Reel, a 9:16 Story and a 1:1 post landed in one row at three different heights — which
 * reads as broken sizing rather than as a range of options. Naming the flagship keeps that page to
 * a single shape, the same way a format-specific page is already scoped to exactly its own size.
 */
export const SOCIAL_HERO_FORMAT: Record<string, string> = {
  youtube: "Thumbnail",
  instagram: "Post",
  tiktok: "Cover",
  pinterest: "Pin",
  x: "Post image",
  linkedin: "Post",
};

