/**
 * No asset may appear in two places.
 *
 * Reusing one image across two sections made edits bleed: swapping the YouTube thumbnail also
 * changed the Channel Kit gallery, because both pointed at the same file. This runs in
 * development only and names the offender rather than leaving it to be spotted on screen.
 */
if (process.env.NODE_ENV !== "production") {
  const seen = new Map<string, string>();
  const claim = (uri: string, owner: string) => {
    if (!uri) return;
    const prior = seen.get(uri);
    if (prior && prior !== owner) {
      console.error(`[examples] ${uri} is used by both "${prior}" and "${owner}" — every section needs its own asset.`);
    } else {
      seen.set(uri, owner);
    }
  };
  for (const [tool, list] of Object.entries(TOOL_EXAMPLES)) {
    for (const e of list) { claim(e.uri, `tool:${tool}`); if (e.before) claim(e.before, `tool:${tool}`); }
  }
  for (const [plat, list] of Object.entries(PLATFORM_SIZE_EXAMPLES)) {
    for (const e of list) claim(e.uri, `platform:${plat}/${e.format}`);
  }
}
